from pathlib import Path
from html.parser import HTMLParser
import hashlib, json, re
source = Path('products/services/nlnet-ai-policy-followup/raw/policy.html')
raw = source.read_bytes()
expected = '4590d76cce8fdb608efe2f1c6eb518d432491c8c2c26992a0be304013d9f8fe8'
actual = hashlib.sha256(raw).hexdigest()
if actual != expected:
    raise SystemExit('Policy capture does not match the recorded FETCH hash')
class Extractor(HTMLParser):
    blocks = {'p', 'li', 'h1', 'h2', 'h3', 'h4', 'blockquote', 'tr', 'div', 'section', 'article'}
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.parts = []
        self.hidden = None
    def handle_starttag(self, tag, attrs):
        if tag in {'script', 'style'}:
            self.hidden = tag
        if tag in self.blocks and self.hidden is None:
            self.parts.append('\n')
    def handle_endtag(self, tag):
        if tag == self.hidden:
            self.hidden = None
        if tag in self.blocks and self.hidden is None:
            self.parts.append('\n')
    def handle_data(self, data):
        if self.hidden is None:
            self.parts.append(data.replace('\n', ' '))
parser = Extractor()
parser.feed(raw.decode('utf-8'))
lines = [' '.join(line.split()) for line in ''.join(parser.parts).splitlines() if line.strip()]
pattern = re.compile(r'generative|\bAI\b|applicant|disclos|responsib|licen[cs]|deliverable|proposal|human|copyright|version|effective', re.I)
indices = sorted({j for i, line in enumerate(lines) if pattern.search(line) for j in range(max(0, i-1), min(len(lines), i+2))})
if not indices:
    raise SystemExit('No relevant policy passages extracted')
output = Path('products/services/nlnet-ai-policy-followup/director-policy-passages.json')
output.parent.mkdir(parents=True, exist_ok=True)
record = {'source_url': 'https://nlnet.nl/foundation/policies/generativeAI/2.0/', 'fetch_receipt': 'TASK-179539920200', 'source_sha256': actual, 'scope': 'Whitespace-normalized source passages. Call applicability and applicant eligibility require separate evidence.', 'passages': [{'line': i+1, 'text': lines[i]} for i in indices]}
output.write_text(json.dumps(record, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
assert json.loads(output.read_text(encoding='utf-8')) == record
print(json.dumps({'artifact': str(output), 'source_sha256': actual, 'passage_count': len(indices)}))
